  [21670] = { "$D1の間、敵のアーマーを$N1低下させます。効果を受けている間、対象はステルスや透明化を使用できません。", "アーマーが$N1低下しています。\n隠密や透明化を使用できません。", 0x8b009da8, 0x0730b87e, "uu" },
